private void setAttackID(int id) {
    this.attackID = id;
    this.attackTimer = 0;
    this.level.broadcastEntityEvent(this, (byte) -id);
}

public void handleEntityEvent(byte id) {
    if (id <= 0) {
        this.attackID = Math.abs(id);
        this.attackTimer = 0;
    } else {
